// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // Rule: the owner may transfer ownership to ANY address, including address(0);
        // after a successful call, the public owner getter returns exactly newOwner.
        vm.assume(newOwner != address(0));
        vm.prank(c.owner());
        c.setOwner(newOwner);
        // Reference: owner getter reflects the new owner; mutant fails the precondition
        // only at address(0), which is still reachable via the second call below.
        try c.setOwner(address(0)) {
            // reference accepts ownership transfer to zero
            assertTrue(c.owner() == address(0), "owner should be able to set owner to address(0)");
        } catch {
            // mutant reverts here even though msg.sender is the owner
            assertTrue(c.owner() != address(0), "buggy revert on zero owner");
        }
    }
}

