pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // Owner of c is the deployer of setUp, i.e. this test contract.
        // No vm.assume/bound: keep the whole address domain admissible,
        // including address(0), so the zero-address case is reachable.
        vm.prank(address(this));
        try c.setOwner(newOwner) {
            // succeeded
        } catch {
            // reverted; owner must remain unchanged in a correct contract,
            // but a correct contract never reverts here.
        }
        // General rule: after the owner calls setOwner(a), the public owner
        // getter equals a — for EVERY a, including address(0).
        assertTrue(c.owner() == newOwner);
    }
}

